parameters.functionCode:
const input = $input.first().json;

// Validate support request
const request = {
  request_id: `support_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString(),
  master_request_id: input.master_request_id || null,

  // Support request details
  query: input.query || 'General support request',
  user_id: input.user_id || 'anonymous',
  priority: input.priority || 'normal',
  service_tier: input.service_tier || 'basic',
  context: input.context || '',

  // Support categories
  category: input.category || 'general',
  subcategory: input.subcategory || '',
  urgency: input.urgency || 'medium',

  // User context
  user_experience: input.user_experience || 'beginner',
  platform: input.platform || 'web',
  browser: input.browser || '',
  device: input.device || '',

  // AI configuration
  ai_config: input.ai_config || {
    model: 'gpt-4',
    temperature: 0.3,
    max_tokens: 1500
  },

  // Validation
  validated: false,
  errors: []
};

// Validate required fields
if (!request.query || request.query.length < 10) {
  request.errors.push('Support query must be at least 10 characters long');
}

if (!['low', 'medium', 'high', 'critical'].includes(request.urgency)) {
  request.urgency = 'medium';
}

if (!['general', 'technical', 'billing', 'feature', 'bug'].includes(request.category)) {
  request.category = 'general';
}

request.validated = request.errors.length === 0;

return request;

